<?php declare(strict_types=1); $this->layout('layouts/default',['title'=>$title,'currentPage'=>'categories']); $labels=['article_category'=>'Artigos','project_category'=>'Projetos','faq_category'=>'FAQ']; ?>
<section class="studio-page">
<header class="studio-page-heading"><div><p class="studio-eyebrow">ORGANIZAÇÃO</p><h2>Categorias</h2><p>Organize artigos, projetos e perguntas do CMS com categorias reutilizáveis.</p></div></header>
<form class="studio-filter-bar" method="get"><label><span>Busca</span><input name="q" value="<?= $this->e($q) ?>" placeholder="Nome ou slug"></label><label><span>Tipo</span><select name="type"><option value="">Todos</option><?php foreach($labels as $value=>$label):?><option value="<?= $value ?>"<?= $type===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><button>Filtrar</button><a href="/studio/categories">Limpar</a></form>
<section class="studio-panel"><h3>Nova categoria</h3><form class="studio-inline-create" method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="save"><label><span>Nome</span><input name="name" minlength="2" maxlength="120" required placeholder="Ex.: Tutoriais"></label><label><span>Usar em</span><select name="type" required><?php foreach($labels as $value=>$label):?><option value="<?= $value ?>"><?= $label ?></option><?php endforeach;?></select></label><button class="studio-btn primary"><?= studio_icon('add') ?> Criar categoria</button></form></section>
<div class="studio-table-wrap"><table><thead><tr><th>Categoria</th><th>Slug</th><th>Tipo</th><th>Uso</th><th>Ações</th></tr></thead><tbody><?php if($categories===[]):?><tr><td colspan="5" class="studio-empty">Nenhuma categoria encontrada.</td></tr><?php endif;?><?php foreach($categories as $category):?><tr><td><form class="studio-inline-form" method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)$category['id'] ?>"><input type="hidden" name="type" value="<?= $this->e($category['type']) ?>"><input name="name" minlength="2" maxlength="120" required value="<?= $this->e($category['name']) ?>"><button class="studio-icon-action" title="Salvar categoria" aria-label="Salvar categoria"><?= studio_icon('save') ?></button></form></td><td>/<?= $this->e($category['slug']) ?></td><td><?= $this->e($labels[$category['type']]??$category['type']) ?></td><td><?= (int)$category['usage_count'] ?></td><td><form method="post" data-confirm-submit="Excluir esta categoria?"><?= $this->csrf() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$category['id'] ?>"><button class="studio-danger-button"<?= (int)$category['usage_count']>0?' disabled title="Categoria em uso"':'' ?>><?= studio_icon('trash') ?> Excluir</button></form></td></tr><?php endforeach;?></tbody></table></div>
</section>
